CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.team_members (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE NOT NULL, name text NOT NULL, email text UNIQUE NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.team_members TO authenticated; GRANT ALL ON public.team_members TO service_role;
ALTER TABLE public.team_members ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.team_roles (user_id uuid PRIMARY KEY, role text NOT NULL CHECK (role IN ('super_admin','employee')));
GRANT SELECT ON public.team_roles TO authenticated; GRANT ALL ON public.team_roles TO service_role;
ALTER TABLE public.team_roles ENABLE ROW LEVEL SECURITY;
INSERT INTO public.profiles(id,full_name) SELECT u.id,coalesce(nullif(u.raw_user_meta_data->>'full_name',''),split_part(u.email,'@',1)) FROM auth.users u JOIN public.user_roles r ON r.user_id=u.id WHERE r.role='admin' ON CONFLICT DO NOTHING;
INSERT INTO public.team_members(user_id,name,email) SELECT p.id,p.full_name,u.email FROM public.profiles p JOIN auth.users u ON u.id=p.id ON CONFLICT DO NOTHING;
INSERT INTO public.team_roles(user_id,role) SELECT user_id,CASE WHEN row_number() OVER (ORDER BY created_at,id)=1 THEN 'super_admin' ELSE 'employee' END FROM public.team_members ON CONFLICT DO NOTHING;
CREATE FUNCTION public.team_access() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT r.role FROM public.team_roles r JOIN public.team_members m ON m.user_id=r.user_id WHERE r.user_id=auth.uid() AND m.is_active $$;
REVOKE ALL ON FUNCTION public.team_access() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.team_access() TO authenticated;
CREATE POLICY "Team reads profiles" ON public.profiles FOR SELECT TO authenticated USING (public.team_access() IS NOT NULL);
CREATE POLICY "Team reads members" ON public.team_members FOR SELECT TO authenticated USING (public.team_access() IS NOT NULL);
CREATE POLICY "Read own team role" ON public.team_roles FOR SELECT TO authenticated USING (user_id=auth.uid() OR public.team_access()='super_admin');
ALTER TABLE public.orders ADD COLUMN assigned_member_id uuid REFERENCES public.team_members(id), ADD COLUMN response_file_paths text[] NOT NULL DEFAULT '{}';
CREATE TABLE public.order_audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES public.orders(id), actor_id uuid, actor_name text NOT NULL, action_type text NOT NULL CHECK(action_type IN ('STATUS_CHANGE','ASSIGNMENT_CHANGE','NOTE','SYSTEM_EVENT')), description text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.order_audit_logs TO authenticated; GRANT ALL ON public.order_audit_logs TO service_role;
ALTER TABLE public.order_audit_logs ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Team reads audit" ON public.order_audit_logs FOR SELECT TO authenticated USING (public.team_access() IS NOT NULL);
CREATE FUNCTION public.audit_order_changes() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE actor text; old_name text; new_name text; BEGIN
SELECT name INTO actor FROM public.team_members WHERE user_id=auth.uid(); actor:=coalesce(actor,'SISTEMA');
IF TG_OP='INSERT' THEN INSERT INTO public.order_audit_logs(order_id,actor_id,actor_name,action_type,description) VALUES(NEW.id,auth.uid(),actor,'SYSTEM_EVENT','Užsakymas sukurtas'); RETURN NEW; END IF;
IF NEW.status IS DISTINCT FROM OLD.status THEN INSERT INTO public.order_audit_logs(order_id,actor_id,actor_name,action_type,description) VALUES(NEW.id,auth.uid(),actor,'STATUS_CHANGE','Būsena: '||OLD.status||' ➔ '||NEW.status); END IF;
IF NEW.assigned_member_id IS DISTINCT FROM OLD.assigned_member_id THEN SELECT name INTO old_name FROM public.team_members WHERE id=OLD.assigned_member_id; SELECT name INTO new_name FROM public.team_members WHERE id=NEW.assigned_member_id; INSERT INTO public.order_audit_logs(order_id,actor_id,actor_name,action_type,description) VALUES(NEW.id,auth.uid(),actor,'ASSIGNMENT_CHANGE','Priskyrimas: '||coalesce(old_name,'Nepriskirta')||' ➔ '||coalesce(new_name,'Nepriskirta')); END IF;
IF NEW.payment_status IS DISTINCT FROM OLD.payment_status THEN INSERT INTO public.order_audit_logs(order_id,actor_name,action_type,description) VALUES(NEW.id,'SISTEMA','SYSTEM_EVENT','Apmokėjimas: '||OLD.payment_status||' ➔ '||NEW.payment_status); END IF;
IF NEW.response_file_paths IS DISTINCT FROM OLD.response_file_paths THEN INSERT INTO public.order_audit_logs(order_id,actor_id,actor_name,action_type,description) VALUES(NEW.id,auth.uid(),actor,'SYSTEM_EVENT','Įkeltas atsakymo dokumentas'); END IF; RETURN NEW; END $$;
CREATE TRIGGER order_changes_audit AFTER INSERT OR UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.audit_order_changes();
CREATE FUNCTION public.team_orders() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE access text:=public.team_access(); result jsonb; BEGIN IF access IS NULL THEN RAISE EXCEPTION 'Prieiga negalima'; END IF; SELECT coalesce(jsonb_agg(CASE WHEN access='super_admin' THEN to_jsonb(o) ELSE to_jsonb(o)-'price' END ORDER BY o.created_at DESC),'[]'::jsonb) INTO result FROM public.orders o; RETURN result; END $$;
CREATE FUNCTION public.change_team_order(order_uuid uuid, work_status text DEFAULT NULL, member_uuid uuid DEFAULT NULL, change_assignment boolean DEFAULT false, note_text text DEFAULT NULL, response_path text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE actor text; BEGIN
IF public.team_access() IS NULL THEN RAISE EXCEPTION 'Prieiga negalima'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.orders WHERE id=order_uuid) THEN RAISE EXCEPTION 'Užsakymas nerastas'; END IF;
IF work_status IS NOT NULL THEN IF work_status NOT IN ('Naujas','Vykdoma','Atlikta','Atšaukta') THEN RAISE EXCEPTION 'Netinkama darbo būsena'; END IF; UPDATE public.orders SET status=work_status WHERE id=order_uuid; END IF;
IF change_assignment THEN IF member_uuid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.team_members WHERE id=member_uuid AND is_active) THEN RAISE EXCEPTION 'Darbuotojas neaktyvus'; END IF; UPDATE public.orders SET assigned_member_id=member_uuid WHERE id=order_uuid; END IF;
IF note_text IS NOT NULL THEN IF length(trim(note_text)) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Pastaba turi būti 1–2000 simbolių'; END IF; SELECT name INTO actor FROM public.team_members WHERE user_id=auth.uid(); INSERT INTO public.order_audit_logs(order_id,actor_id,actor_name,action_type,description) VALUES(order_uuid,auth.uid(),actor,'NOTE',trim(note_text)); END IF;
IF response_path IS NOT NULL THEN IF response_path NOT LIKE 'responses/'||order_uuid::text||'/%' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='order-documents' AND name=response_path AND owner_id=auth.uid()::text) THEN RAISE EXCEPTION 'Dokumentas nerastas'; END IF; UPDATE public.orders SET response_file_paths=array_append(response_file_paths,response_path) WHERE id=order_uuid; END IF;
END $$;
CREATE FUNCTION public.manage_team_member(target_user uuid, display_name text, member_email text, new_role text, active boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
PERFORM pg_advisory_xact_lock(839410);
IF public.team_access() IS DISTINCT FROM 'super_admin' THEN RAISE EXCEPTION 'Tik vadovas gali valdyti komandą'; END IF;
IF new_role NOT IN ('super_admin','employee') OR length(trim(display_name)) NOT BETWEEN 1 AND 120 THEN RAISE EXCEPTION 'Neteisingi darbuotojo duomenys'; END IF;
IF EXISTS(SELECT 1 FROM public.team_roles r JOIN public.team_members m ON m.user_id=r.user_id WHERE r.user_id=target_user AND r.role='super_admin' AND m.is_active) AND (NOT active OR new_role<>'super_admin') AND (SELECT count(*) FROM public.team_roles r JOIN public.team_members m ON m.user_id=r.user_id WHERE r.role='super_admin' AND m.is_active)<=1 THEN RAISE EXCEPTION 'Negalima pašalinti paskutinio vadovo'; END IF;
INSERT INTO public.profiles(id,full_name) VALUES(target_user,trim(display_name)) ON CONFLICT(id) DO UPDATE SET full_name=excluded.full_name;
INSERT INTO public.team_members(user_id,name,email,is_active) VALUES(target_user,trim(display_name),lower(member_email),active) ON CONFLICT(user_id) DO UPDATE SET name=excluded.name,email=excluded.email,is_active=excluded.is_active;
INSERT INTO public.team_roles(user_id,role) VALUES(target_user,new_role) ON CONFLICT(user_id) DO UPDATE SET role=excluded.role;
DELETE FROM public.user_roles WHERE user_id=target_user AND role='admin';
END $$;
REVOKE ALL ON FUNCTION public.team_orders(),public.change_team_order(uuid,text,uuid,boolean,text,text),public.manage_team_member(uuid,text,text,text,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.team_orders(),public.change_team_order(uuid,text,uuid,boolean,text,text),public.manage_team_member(uuid,text,text,text,boolean) TO authenticated;
REVOKE UPDATE ON public.orders FROM authenticated;
CREATE POLICY "Team reads order documents" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='order-documents' AND public.team_access() IS NOT NULL);
CREATE POLICY "Team uploads responses" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='order-documents' AND public.team_access() IS NOT NULL AND (storage.foldername(name))[1]='responses' AND EXISTS(SELECT 1 FROM public.orders WHERE id::text=(storage.foldername(name))[2]));